		name: screen.name,
		widthMm: screen.widthMm,
		heightMm: screen.heightMm,
		pixelWidth: screen.pixelWidth,
		pixelHeight: screen.pixelHeight,
		xMm: screen.xMm,
		yMm: screen.yMm,
		rotationDeg: screen.rotationDeg
